export interface UserProfile {
  name: string;
  role: string;
  greetingDate: string;
  streakDays: number;
  targetScore: string;
  todayGoalText: string;
}

export interface ProgressSummary {
  lastExam: {
    title: string;
    completedAt: string;
    score: number;
    maxScore: number;
    targetScore: number;
    pointsNeeded: number;
  };
  lastVocab: {
    title: string;
    subTitle: string;
    completedAt: string;
    memorizedCount: number;
    totalCount: number;
  };
  lastGrammar: {
    title: string;
    studiedAt: string;
  };
}

export interface ExamItem {
  id: string;
  title: string;
  description: string;
  category: 'ETS' | 'HACKER' | 'BIG STEP' | 'ECONOMY';
  badgeType: 'Full Test' | 'Nâng cao';
  status: 'completed' | 'in_progress' | 'not_started';
  scoreBadge?: string;
  progressPercent: number;
  progressText?: string;
  durationMinutes: number;
  totalQuestions: number;
  attemptCount: string;
  currentQuestion?: number;
}

export interface VocabTopic {
  id: string;
  title: string;
  description: string;
  targetLevel: string;
  status: 'completed' | 'in_progress' | 'not_started';
  memorizedCount: number;
  totalCount: number;
  iconType: 'contract' | 'finance' | 'business' | 'personnel' | 'travel' | 'shopping';
}

